-- ===== 26: Layanan Publik (hub) =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<div class="svc-hero"><div><span class="svc-kicker">Pelayanan Terpadu Satu Pintu</span><p class="svc-lead">Seluruh layanan administrasi Pengadilan Negeri Natuna Kelas II dilayani melalui satu meja PTSP: cepat, transparan, tanpa perantara, dan bebas pungutan liar. Halaman ini merangkum seluruh informasi layanan publik bagi masyarakat dan pencari keadilan.</p><ul class="svc-facts"><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Jam layanan hari ini: <strong class="js-service-hours">08.00&#8211;16.30 WIB</strong></li><li><a href="tel:07733211203"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>0773-3211203</a></li><li><a href="mailto:pn.natuna@gmail.com"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>pn.natuna@gmail.com</a></li></ul></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><circle cx="152" cy="36" r="11" fill="#b98f24"/><polygon points="100,30 152,62 48,62" fill="#8f1f0b"/><circle cx="100" cy="50" r="6" fill="#b98f24"/><rect x="56" y="62" width="88" height="8" fill="#671607"/><rect x="60" y="70" width="80" height="44" fill="#ffffff" stroke="#d9e0e7" stroke-width="2"/><rect x="68" y="76" width="10" height="32" rx="2" fill="#e9dfc4"/><rect x="86" y="76" width="10" height="32" rx="2" fill="#e9dfc4"/><rect x="104" y="76" width="10" height="32" rx="2" fill="#e9dfc4"/><rect x="122" y="76" width="10" height="32" rx="2" fill="#e9dfc4"/><rect x="52" y="114" width="96" height="8" rx="3" fill="#8f1f0b"/><rect x="44" y="122" width="112" height="7" rx="3.5" fill="#b98f24"/><ellipse cx="100" cy="140" rx="64" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Jelajahi Layanan</h2><div class="svc-grid"><a class="svc-card" href="/jenis-layanan-ptsp"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><path d="M5 7h14"/><path d="M5 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M19 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M8 21h8"/></svg></span><h3>Jenis Layanan PTSP</h3><p>Layanan kepaniteraan perdata, pidana, dan hukum yang dapat diakses melalui satu meja PTSP.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/standar-pelayanan"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg></span><h3>Standar Pelayanan</h3><p>Pedoman mutu pelayanan peradilan berdasarkan SK KMA Nomor 026/KMA/SK/II/2012.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/maklumat-pelayanan"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="7"/><polyline points="8.21 13.89 7 23 12 20 17 23 15.79 13.88"/></svg></span><h3>Maklumat Pelayanan</h3><p>Pernyataan kesanggupan pengadilan untuk melayani sesuai standar yang telah ditetapkan.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/kompensasi-layanan"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg></span><h3>Kompensasi Layanan</h3><p>Bentuk tanggung jawab pengadilan apabila pelayanan tidak sesuai standar yang berlaku.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/layanan-disabilitas"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="13" cy="4" r="2"/><path d="M13 7v5h5l2 5"/><path d="M13 9h4"/><circle cx="11" cy="17" r="4"/></svg></span><h3>Layanan Disabilitas</h3><p>Fasilitas, aksesibilitas, dan pendampingan bagi penyandang disabilitas serta kelompok rentan.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/permohonan-informasi"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg></span><h3>Permohonan Informasi</h3><p>Prosedur memperoleh informasi publik melalui petugas informasi dan PPID pengadilan.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/regulasi-pengaduan"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg></span><h3>Pengaduan</h3><p>Dasar hukum dan kanal resmi penyampaian pengaduan, termasuk aplikasi SIWAS MA RI.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/tata-tertib-pengadilan"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1"/></svg></span><h3>Tata Tertib di Pengadilan</h3><p>Ketentuan yang wajib dipatuhi pengunjung selama berada di lingkungan pengadilan.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><a class="svc-card" href="/tata-tertib-ruang-sidang"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span><h3>Tata Tertib Ruang Sidang</h3><p>Adab dan aturan yang berlaku selama persidangan berlangsung.</p><span class="svc-more">Selengkapnya <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a></div><div class="svc-cta"><div><h2>Butuh bantuan atau informasi cepat?</h2><p>Petugas PTSP kami siap membantu pada jam layanan. Anda juga dapat mengajukan perkara secara elektronik melalui e-Court Mahkamah Agung RI.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>Hubungi via WhatsApp</a><a class="svc-btn svc-btn-line" href="https://ecourt.mahkamahagung.go.id/" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>e-Court MA RI</a></div></div>' WHERE id = 26;

-- ===== 11: Jenis Layanan PTSP =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp" aria-current="page">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Satu Pintu, Satu Meja</span><p class="svc-lead">Pelayanan Terpadu Satu Pintu (PTSP) Pengadilan Negeri Natuna memberikan layanan administrasi peradilan secara terpadu, tertib, dan mudah diakses masyarakat. Seluruh permohonan cukup disampaikan melalui meja PTSP tanpa perlu menemui pejabat atau pegawai lain.</p><ul class="svc-facts"><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Jam layanan hari ini: <strong class="js-service-hours">08.00&#8211;16.30 WIB</strong></li><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>Bebas biaya perantara</li></ul></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><circle cx="86" cy="52" r="11" fill="#244b6d"/><path d="M66 92c0-12 9-20 20-20s20 8 20 20" fill="#244b6d"/><rect x="120" y="30" width="46" height="30" rx="9" fill="#b98f24"/><polygon points="130,58 130,70 142,58" fill="#b98f24"/><polyline points="133,45 140,52 153,39" fill="none" stroke="#ffffff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><rect x="112" y="74" width="26" height="16" rx="2" fill="#ffffff" stroke="#d9e0e7" stroke-width="2"/><rect x="48" y="92" width="104" height="30" rx="6" fill="#8f1f0b"/><rect x="44" y="88" width="112" height="8" rx="4" fill="#671607"/><ellipse cx="100" cy="136" rx="60" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Layanan per Kepaniteraan</h2><div class="svc-grid"><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><path d="M5 7h14"/><path d="M5 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M19 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M8 21h8"/></svg></span><h3>Kepaniteraan Perdata</h3><ul><li>Pendaftaran gugatan biasa, gugatan sederhana, perlawanan, verzet, dan permohonan.</li><li>Pendaftaran upaya hukum banding, kasasi, peninjauan kembali, serta penerimaan memori dan kontra memori.</li><li>Permohonan salinan putusan, akta cerai, informasi perkara, dan layanan administrasi perkara perdata lainnya.</li></ul></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg></span><h3>Kepaniteraan Pidana</h3><ul><li>Penerimaan pelimpahan berkas perkara pidana.</li><li>Layanan upaya hukum banding, kasasi, dan peninjauan kembali perkara pidana.</li><li>Permohonan izin besuk tahanan, surat keterangan, dan layanan administrasi pidana lainnya sesuai ketentuan.</li></ul></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg></span><h3>Kepaniteraan Hukum</h3><ul><li>Permohonan informasi publik.</li><li>Surat keterangan tidak pernah dipidana dan layanan surat keterangan lain sesuai ketentuan.</li><li>Layanan legalisasi, riset, dan informasi hukum yang tersedia di pengadilan.</li></ul></div></div><h2>Dokumen Informasi Layanan</h2><div class="svc-grid"><div><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/biaya-jenis-layanan.png" data-maklumat-label="Jenis dan Biaya Layanan Pengadilan Negeri Natuna" aria-label="Perbesar dokumen jenis dan biaya layanan"><img src="/images/layanan/biaya-jenis-layanan.png" alt="Jenis dan biaya layanan Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><span class="svc-zoom-caption">Jenis dan Biaya Layanan</span></div><div><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/waktu-layanan.png" data-maklumat-label="Waktu Pelayanan Pengadilan Negeri Natuna" aria-label="Perbesar dokumen waktu pelayanan"><img src="/images/layanan/waktu-layanan.png" alt="Waktu pelayanan Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><span class="svc-zoom-caption">Waktu Pelayanan</span></div></div><div class="svc-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><p>Rincian jenis layanan akan terus disesuaikan dengan ketentuan terbaru dan standar pelayanan yang berlaku. Untuk kepastian persyaratan, silakan hubungi petugas PTSP terlebih dahulu.</p></div><div class="svc-cta"><div><h2>Urus perkara tanpa datang ke pengadilan</h2><p>Pendaftaran perkara, pembayaran, dan persidangan tertentu dapat dilakukan secara elektronik melalui e-Court Mahkamah Agung RI.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="https://ecourt.mahkamahagung.go.id/" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>Buka e-Court</a><a class="svc-btn svc-btn-line" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>Tanya Petugas</a></div></div>' WHERE id = 11;

-- ===== 12: Standar Pelayanan =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan" aria-current="page">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Jaminan Mutu Pelayanan</span><p class="svc-lead">Standar pelayanan peradilan menjadi tolok ukur bagi pengadilan dalam melayani masyarakat dan pencari keadilan. Pengadilan Negeri Natuna berpedoman pada Surat Keputusan Ketua Mahkamah Agung RI Nomor 026/KMA/SK/II/2012 tentang Standar Pelayanan Peradilan.</p></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><rect x="66" y="30" width="70" height="92" rx="7" fill="#ffffff" stroke="#d9e0e7" stroke-width="2"/><rect x="76" y="44" width="50" height="6" rx="3" fill="#8f1f0b" opacity="0.85"/><rect x="76" y="58" width="42" height="5" rx="2.5" fill="#dfe5eb"/><rect x="76" y="70" width="46" height="5" rx="2.5" fill="#dfe5eb"/><rect x="76" y="82" width="38" height="5" rx="2.5" fill="#dfe5eb"/><polygon points="120,104 126,118 114,118" fill="#b98f24"/><polygon points="130,104 136,118 124,118" fill="#8f1f0b"/><circle cx="125" cy="100" r="13" fill="#b98f24"/><circle cx="125" cy="100" r="7" fill="#fbf2d8"/><circle cx="62" cy="42" r="15" fill="#1f5b4b"/><polyline points="55,42 60,47 70,36" fill="none" stroke="#ffffff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="100" cy="136" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Ruang Lingkup Standar Pelayanan</h2><div class="svc-grid"><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><path d="M5 7h14"/><path d="M5 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M19 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M8 21h8"/></svg></span><h3>Pelayanan Persidangan</h3><p>Kepastian jadwal sidang, tata cara persidangan, dan hak para pihak selama proses berjalan.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg></span><h3>Biaya Perkara</h3><p>Transparansi komponen dan besaran panjar biaya perkara serta pengembalian sisa panjar.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span><h3>Bantuan Hukum</h3><p>Layanan pembebasan biaya perkara dan Posbakum bagi masyarakat yang tidak mampu.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg></span><h3>Informasi Publik</h3><p>Hak masyarakat memperoleh informasi pengadilan sesuai ketentuan keterbukaan informasi.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg></span><h3>Pengaduan</h3><p>Mekanisme penyampaian dan penanganan pengaduan atas pelayanan pengadilan.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg></span><h3>Pelayanan Administratif</h3><p>Layanan surat keterangan, salinan putusan, legalisasi, dan administrasi kepaniteraan lainnya.</p></div></div><h2>Dokumen Standar Pelayanan</h2><div class="svc-docs"><a class="svc-doc" href="https://drive.google.com/file/d/1z2loaW19M6rHRBe12_LaWA3e27ib5yfJ/view?usp=sharing" target="_blank" rel="noopener"><span class="svc-doc-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></span><span><strong>SK KMA Nomor 026/KMA/SK/II/2012</strong><span>Standar Pelayanan Peradilan &#8212; dokumen utama</span></span></a><a class="svc-doc" href="https://drive.google.com/file/d/1CX9lbNWZdZ4OlZUkEYPdIIl0fKHiR6ZJ/view?usp=sharing" target="_blank" rel="noopener"><span class="svc-doc-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></span><span><strong>Lampiran SK KMA Nomor 026/KMA/SK/II/2012</strong><span>Rincian standar tiap jenis pelayanan</span></span></a></div><div class="svc-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><p>Apabila pelayanan yang Anda terima tidak sesuai standar, Anda berhak menyampaikan pengaduan melalui <a href="/regulasi-pengaduan">kanal pengaduan resmi</a> dan memperoleh <a href="/kompensasi-layanan">kompensasi layanan</a>.</p></div>' WHERE id = 12;

-- ===== 13: Maklumat Pelayanan =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan" aria-current="page">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Komitmen Pelayanan</span><p class="svc-lead">Maklumat pelayanan merupakan pernyataan kesanggupan Pengadilan Negeri Natuna untuk menyelenggarakan pelayanan sesuai standar pelayanan yang berlaku &#8212; sekaligus kesediaan menerima sanksi apabila janji itu tidak ditepati.</p></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><rect x="56" y="32" width="88" height="88" rx="7" fill="#ffffff" stroke="#d9e0e7" stroke-width="2"/><rect x="64" y="40" width="72" height="72" rx="4" fill="none" stroke="#e9dfc4" stroke-width="2"/><rect x="76" y="50" width="48" height="7" rx="3.5" fill="#8f1f0b"/><rect x="80" y="64" width="40" height="5" rx="2.5" fill="#dfe5eb"/><rect x="76" y="76" width="48" height="5" rx="2.5" fill="#dfe5eb"/><circle cx="100" cy="102" r="11" fill="#b98f24"/><circle cx="100" cy="102" r="5.5" fill="#fbf2d8"/><polygon points="94,110 90,124 100,117 110,124 106,110" fill="#8f1f0b"/><ellipse cx="100" cy="138" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><blockquote><p>&#8220;Sanggup untuk menyelenggarakan pelayanan peradilan dengan standar yang telah ditetapkan, dan apabila kami tidak menepati standar pelayanan tersebut kami siap menerima sanksi sesuai peraturan yang berlaku.&#8221;</p><footer>Lodewyk Ivandrie Simanjuntak, S.H., M.H. &#8212; Ketua Pengadilan Negeri Natuna</footer></blockquote><h2>Dokumen Maklumat</h2><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/maklumat-pelayanan-2026.jpg" data-maklumat-label="Maklumat Pelayanan Pengadilan Negeri Natuna" aria-label="Perbesar dokumen maklumat pelayanan"><img src="/images/layanan/maklumat-pelayanan-2026.jpg" alt="Maklumat Pelayanan Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><div class="svc-docs"><a class="svc-doc" href="https://drive.google.com/file/d/1aeePwb1ryGocKMA96D37pn_gHmAweO5G/view?usp=sharing" target="_blank" rel="noopener"><span class="svc-doc-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></span><span><strong>Dokumen Maklumat Pelayanan</strong><span>Unduh atau lihat versi lengkap</span></span></a></div><div class="svc-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><p>Untuk layanan informasi publik, tersedia pula <a href="/permohonan-informasi">Maklumat Layanan Informasi Publik</a> yang ditandatangani PPID Pengadilan Negeri Natuna.</p></div>' WHERE id = 13;

-- ===== 14: Kompensasi Layanan =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan" aria-current="page">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Jaminan Layanan</span><p class="svc-lead">Sebagai bentuk tanggung jawab atas mutu pelayanan publik, Pengadilan Negeri Natuna memberikan kompensasi kepada pengguna layanan apabila pelayanan yang diberikan tidak sesuai dengan standar pelayanan yang telah ditetapkan.</p></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><path d="M100 26l42 15v30c0 28-42 47-42 47s-42-19-42-47V41z" fill="#8f1f0b"/><path d="M100 36l32 11v24c0 21-32 36-32 36s-32-15-32-36V47z" fill="#671607"/><path d="M100 62c4-7 14-7 17 0 3 6-3 12-17 22-14-10-20-16-17-22 3-7 13-7 17 0z" fill="#b98f24"/><circle cx="150" cy="42" r="5" fill="#b98f24"/><circle cx="52" cy="56" r="4" fill="#b98f24"/><circle cx="146" cy="98" r="4" fill="#1f5b4b" opacity="0.5"/><ellipse cx="100" cy="136" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Bentuk Kompensasi</h2><div class="svc-grid"><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></span><h3>Permohonan Maaf</h3><p>Penyampaian permohonan maaf secara langsung atau tertulis kepada pengguna layanan yang dirugikan.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg></span><h3>Perbaikan Layanan</h3><p>Perbaikan atau pengulangan layanan sesegera mungkin agar hak pengguna layanan tetap terpenuhi.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg></span><h3>Prioritas Penanganan</h3><p>Layanan yang tertunda diprioritaskan penyelesaiannya sesuai ketentuan yang berlaku.</p></div></div><h2>Cara Menyampaikan Keluhan</h2><ol class="svc-steps"><li><strong>Sampaikan keluhan Anda</strong><span>Melalui petugas PTSP, meja pengaduan, atau aplikasi SIWAS MA RI dengan menyertakan bukti layanan.</span></li><li><strong>Verifikasi oleh petugas</strong><span>Petugas memeriksa kesesuaian layanan yang diterima dengan standar pelayanan yang berlaku.</span></li><li><strong>Kompensasi diberikan</strong><span>Apabila terbukti tidak sesuai standar, kompensasi diberikan sesuai ketentuan yang berlaku.</span></li></ol><h2>Dokumen Kompensasi Layanan</h2><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/kompensasi.png" data-maklumat-label="Kompensasi Layanan Pengadilan Negeri Natuna" aria-label="Perbesar dokumen kompensasi layanan"><img src="/images/layanan/kompensasi.png" alt="Kompensasi layanan Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><div class="svc-cta"><div><h2>Layanan kami belum sesuai harapan?</h2><p>Sampaikan pengaduan Anda &#8212; setiap masukan membantu kami memperbaiki mutu pelayanan.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="/regulasi-pengaduan"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>Kanal Pengaduan</a><a class="svc-btn svc-btn-line" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>WhatsApp Kami</a></div></div>' WHERE id = 14;

-- ===== 15: Layanan Disabilitas =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas" aria-current="page">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Peradilan Inklusif</span><p class="svc-lead">Pengadilan Negeri Natuna berkomitmen memberikan layanan yang setara, mudah diakses, dan tidak diskriminatif bagi penyandang disabilitas, lansia, ibu hamil, serta kelompok rentan lainnya.</p></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><polygon points="58,122 148,122 148,92" fill="#1f5b4b" opacity="0.22"/><circle cx="92" cy="100" r="22" fill="none" stroke="#8f1f0b" stroke-width="7"/><circle cx="124" cy="116" r="7" fill="#8f1f0b"/><circle cx="96" cy="40" r="10" fill="#244b6d"/><path d="M96 52v24h26l10 20" fill="none" stroke="#244b6d" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><path d="M96 62h20" stroke="#244b6d" stroke-width="7" stroke-linecap="round"/><circle cx="146" cy="46" r="9" fill="#b98f24"/><ellipse cx="100" cy="140" rx="60" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Prinsip Layanan</h2><div class="svc-grid"><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><path d="M5 7h14"/><path d="M5 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M19 7l-3 6a3.5 3.5 0 0 0 6 0z"/><path d="M8 21h8"/></svg></span><h3>Perlakuan Setara</h3><p>Setiap pengguna layanan dilayani tanpa diskriminasi dalam bentuk apa pun.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="13" cy="4" r="2"/><path d="M13 7v5h5l2 5"/><path d="M13 9h4"/><circle cx="11" cy="17" r="4"/></svg></span><h3>Aksesibilitas</h3><p>Akses fisik gedung dan akses informasi disiapkan agar mudah dijangkau semua orang.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></span><h3>Komunikasi Mudah</h3><p>Informasi disampaikan dengan cara yang mudah dipahami sesuai kebutuhan pengguna layanan.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span><h3>Prioritas Pendampingan</h3><p>Petugas siap mendampingi pengguna layanan yang membutuhkan bantuan sejak tiba di pengadilan.</p></div></div><h2>Sarana dan Prasarana</h2><div class="svc-grid"><div class="svc-card"><h3>Ramp dan Akses Masuk</h3><p>Jalur landai yang memudahkan pengguna kursi roda memasuki gedung pengadilan.</p></div><div class="svc-card"><h3>Kursi Roda dan Alat Bantu</h3><p>Tersedia sesuai ketersediaan satuan kerja dan dapat diminta melalui petugas.</p></div><div class="svc-card"><h3>Ruang Tunggu Prioritas</h3><p>Ruang tunggu dan jalur layanan yang lebih mudah diakses kelompok rentan.</p></div><div class="svc-card"><h3>Bantuan Petugas PTSP</h3><p>Seluruh informasi layanan dapat dibantu dan dijelaskan langsung oleh petugas.</p></div></div><h2>Fasilitas Akses</h2><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/akses-disabilitas.jpg" data-maklumat-label="Fasilitas akses disabilitas Pengadilan Negeri Natuna" aria-label="Perbesar foto fasilitas akses disabilitas"><img src="/images/layanan/akses-disabilitas.jpg" alt="Fasilitas akses disabilitas Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><div class="svc-cta"><div><h2>Butuh pendampingan saat berkunjung?</h2><p>Beri tahu kami sebelum kedatangan Anda agar petugas dapat menyiapkan bantuan yang diperlukan.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>Hubungi via WhatsApp</a><a class="svc-btn svc-btn-line" href="tel:07733211203"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>0773-3211203</a></div></div>' WHERE id = 15;

-- ===== 19: Prosedur Permohonan Informasi =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi" aria-current="page">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Keterbukaan Informasi Publik</span><p class="svc-lead">Permohonan informasi di Pengadilan Negeri Natuna dilayani melalui prosedur biasa dan prosedur khusus sesuai Keputusan Ketua Mahkamah Agung RI Nomor 2-144/KMA/SK/VIII/2022 tentang Standar Pelayanan Informasi Publik di Pengadilan.</p><ul class="svc-facts"><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Jam layanan hari ini: <strong class="js-service-hours">08.00&#8211;16.30 WIB</strong></li><li><a href="mailto:pn.natuna@gmail.com"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>pn.natuna@gmail.com</a></li></ul></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><rect x="56" y="36" width="60" height="80" rx="6" fill="#ffffff" stroke="#d9e0e7" stroke-width="2"/><rect x="65" y="48" width="40" height="5" rx="2.5" fill="#dfe5eb"/><rect x="65" y="60" width="34" height="5" rx="2.5" fill="#dfe5eb"/><rect x="65" y="72" width="38" height="5" rx="2.5" fill="#dfe5eb"/><circle cx="118" cy="88" r="21" fill="rgba(251,242,216,0.55)" stroke="#b98f24" stroke-width="7"/><line x1="133" y1="103" x2="148" y2="118" stroke="#b98f24" stroke-width="8" stroke-linecap="round"/><circle cx="146" cy="42" r="14" fill="#244b6d"/><rect x="144" y="40" width="4" height="10" rx="2" fill="#ffffff"/><circle cx="146" cy="34.5" r="2.4" fill="#ffffff"/><ellipse cx="100" cy="136" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Dua Jalur Prosedur</h2><div class="svc-grid"><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg></span><h3>Prosedur Biasa</h3><p>Digunakan apabila permohonan disampaikan tidak langsung, informasi bervolume besar, informasi belum tersedia, atau memerlukan penelaahan PPID terlebih dahulu.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg></span><h3>Prosedur Khusus</h3><p>Digunakan untuk permohonan langsung terhadap informasi yang wajib diumumkan, tersedia setiap saat, atau dapat diberikan segera sesuai ketentuan.</p></div></div><h2>Alur Permohonan</h2><ol class="svc-steps"><li><strong>Ajukan permohonan</strong><span>Datang langsung ke petugas informasi atau meja PTSP, atau sampaikan secara tertulis melalui surat maupun email resmi pengadilan.</span></li><li><strong>Registrasi dan tanda terima</strong><span>Permohonan dicatat dalam register dan pemohon menerima tanda bukti permohonan informasi.</span></li><li><strong>Pemenuhan informasi</strong><span>Petugas atau PPID menelaah dan menyampaikan informasi, atau memberitahukan alasannya apabila informasi dikecualikan.</span></li><li><strong>Keberatan</strong><span>Apabila tidak puas atas layanan informasi, pemohon dapat mengajukan keberatan kepada atasan PPID sesuai ketentuan.</span></li></ol><h2>Maklumat Layanan Informasi Publik</h2><blockquote><p>&#8220;Siap memberikan pelayanan informasi publik secara cepat, tepat waktu, biaya ringan, dan sederhana sesuai dengan ketentuan peraturan perundang-undangan.&#8221;</p><footer>Jhivo Wilanda, S.H. &#8212; PPID Pengadilan Negeri Natuna</footer></blockquote><button type="button" class="svc-zoom" data-maklumat-zoom="/images/layanan/maklumat-layanan-informasi-publik.png" data-maklumat-label="Maklumat Layanan Informasi Publik Pengadilan Negeri Natuna" aria-label="Perbesar dokumen maklumat layanan informasi publik"><img src="/images/layanan/maklumat-layanan-informasi-publik.png" alt="Maklumat Layanan Informasi Publik Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><div class="svc-cta"><div><h2>Ingin mengajukan permohonan informasi?</h2><p>Petugas informasi kami siap membantu menjelaskan jenis informasi yang tersedia dan persyaratannya.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="mailto:pn.natuna@gmail.com"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>Kirim Email</a><a class="svc-btn svc-btn-line" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>WhatsApp</a></div></div>' WHERE id = 19;

-- ===== 97: Dasar Hukum dan Regulasi Pengaduan =====
UPDATE pnn_content SET `fulltext` = '', introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan" aria-current="page">Pengaduan</a></nav><div class="svc-hero"><div><span class="svc-kicker">Pengawasan dan Pengaduan</span><p class="svc-lead">Pengaduan di lingkungan Mahkamah Agung dan badan peradilan di bawahnya berpedoman antara lain pada Peraturan Mahkamah Agung RI Nomor 9 Tahun 2016 tentang Pedoman Penanganan Pengaduan (Whistleblowing System). Identitas pelapor dijamin kerahasiaannya.</p></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><polygon points="52,78 108,52 108,116 52,92" fill="#8f1f0b"/><rect x="104" y="50" width="12" height="68" rx="5" fill="#671607"/><rect x="60" y="92" width="14" height="26" rx="6" fill="#671607"/><path d="M128 66a26 26 0 0 1 0 38" fill="none" stroke="#b98f24" stroke-width="7" stroke-linecap="round"/><path d="M140 54a44 44 0 0 1 0 62" fill="none" stroke="#b98f24" stroke-width="7" stroke-linecap="round" opacity="0.65"/><circle cx="58" cy="44" r="14" fill="#1f5b4b"/><polyline points="51,44 56,49 66,38" fill="none" stroke="#ffffff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="100" cy="136" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Kanal Pengaduan Resmi</h2><div class="svc-grid"><a class="svc-card" href="https://siwas.mahkamahagung.go.id/" target="_blank" rel="noopener"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg></span><h3>SIWAS MA RI</h3><p>Aplikasi pengaduan daring resmi Badan Pengawasan Mahkamah Agung RI. Dapat diakses kapan saja dan identitas pelapor dirahasiakan.</p><span class="svc-more">Buka SIWAS <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></a><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></span><h3>Meja Pengaduan</h3><p>Datang langsung ke meja pengaduan atau PTSP Pengadilan Negeri Natuna pada jam layanan untuk menyampaikan pengaduan secara tatap muka.</p></div><div class="svc-card"><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg></span><h3>Surat Resmi</h3><p>Kirim pengaduan tertulis ke alamat kantor Pengadilan Negeri Natuna atau melalui kanal resmi lain yang disediakan satuan kerja.</p></div></div><h2>Yang Perlu Disampaikan</h2><ol class="svc-steps"><li><strong>Identitas pelapor</strong><span>Cantumkan identitas sesuai ketentuan. Kerahasiaan identitas pelapor dilindungi.</span></li><li><strong>Uraian peristiwa</strong><span>Jelaskan peristiwa atau dugaan pelanggaran secara jelas: apa, siapa, kapan, dan di mana.</span></li><li><strong>Bukti pendukung</strong><span>Lampirkan dokumen, foto, atau bukti lain apabila tersedia untuk mempercepat penanganan.</span></li></ol><div class="svc-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><p>Setiap pengaduan diproses sesuai ketentuan dan kewenangan yang berlaku. Perkembangan penanganan pengaduan melalui SIWAS dapat dipantau menggunakan nomor register pengaduan.</p></div><div class="svc-cta"><div><h2>Laporkan dugaan pelanggaran</h2><p>Pengaduan Anda membantu menjaga integritas dan mutu pelayanan badan peradilan.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="https://siwas.mahkamahagung.go.id/" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>Lapor via SIWAS</a><a class="svc-btn svc-btn-line" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>WhatsApp Kami</a></div></div>' WHERE id = 97;
